--- handover.js ---
const note=document.querySelector('#note'),status=document.querySelector('#saved'),$=x=>document.querySelector(x);
async function load(){
 const s=await fetch('/api/state',{cache:'no-store'}).then(r=>r.json());
 note.value=s.handover_text||'';$('#resetCount').textContent='Reset: '+s.reset_count+'/2 (3rd = FAIL)';$('#step').textContent=s.step;
 $('#save').disabled=!!s.terminated;
}
$('#save').addEventListener('click',async()=>{
 const b=$('#save');if(b.disabled)return;b.disabled=true;status.textContent='SAVING…';
 try{const d=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:'B',action:'handover',text:note.value})}).then(r=>r.json());
 status.textContent=d.message==='ok'?'SAVED · B → A':'SAVE REJECTED';$('#step').textContent=d.state.step;$('#resetCount').textContent='Reset: '+d.state.reset_count+'/2 (3rd = FAIL)';b.disabled=!!d.state.terminated
 }finally{if(!b.disabled)b.disabled=false}
});
load();


--- panel.js ---
let S=null,chosen=null,busy=false;
const $=x=>document.querySelector(x),nice=x=>String(x||'').replaceAll('_',' ').toUpperCase();
async function reload(){S=await fetch('/api/state',{cache:'no-store'}).then(r=>r.json());if(!chosen||!S.faults.some(f=>f.code===chosen))chosen=S.faults.find(f=>f.status==='open')?.code||S.faults[0].code;paint()}
function paint(){
 if(!S)return;$('#resetCount').textContent='Reset: '+S.reset_count+'/2 (3rd = FAIL)';$('#step').textContent=S.step;$('#resolved').textContent=S.resolved_count+' / 10';
 $('#statusline').textContent=S.status==='failed_reset_limit'?'RESET LIMIT REACHED — SYSTEM FAILED':S.status==='cleared'?'ALL 10 CIRCUITS RESTORED':'10 fault circuits · resolve prerequisites before downstream faults';
 $('#resetBtn').disabled=S.status==='failed_reset_limit';
 let rows=$('#faultRows');rows.replaceChildren();
 for(const f of S.faults){let b=document.createElement('button');b.className='faultRow '+(f.code===chosen?'selected ':'')+f.status+(f.masked?' masked':'');let state=f.masked?'MASKED':f.status.toUpperCase();b.innerHTML='<b></b><span></span><i class="dot"></i>';b.querySelector('b').textContent=f.code;b.querySelector('span').textContent=state;b.onclick=()=>{chosen=f.code;paint()};rows.append(b)}
 let f=S.faults.find(x=>x.code===chosen);if(!f)return;
 $('#code').textContent=f.code;$('#symptom').textContent=f.symptom;
 $('#symptom').classList.toggle('maskedText',!!f.masked);
 let badge=$('#badge');badge.textContent=f.masked?'MASKED':f.status.toUpperCase();badge.className='badge '+(f.status==='resolved'?'resolved':f.status==='locked'?'locked':'open');
 $('#probeCount').textContent=Math.max(0,2-S.test_uses)+' / 2';
 let test=$('#testBtn');test.disabled=!!S.terminated||f.status!=='open'||f.masked||!!f.test_result||S.test_uses>=2;
 test.textContent=f.test_result?'✓ TEST USED':f.masked?'WAIT FOR PREREQUISITE':'◎ TEST SIGNAL';
 document.querySelectorAll('[data-action]').forEach(b=>b.disabled=!!S.terminated||f.status!=='open'||f.masked||(f.requires_test&&!f.test_result));
 $('#hint').textContent=f.masked?f.symptom:f.status==='locked'?'PERMANENT LOCK — this fault cannot be retried.':f.status==='resolved'?'Repair confirmed. Dependent masked faults may now reveal their symptoms.':f.requires_test&&!f.test_result?'This fault needs a probe. Do not guess: both probes are needed for the two ambiguous circuits.':!f.requires_test&&!f.test_result?'This clue is already enough. A probe here gives no extra signal and wastes one of only two.':'A applies here. B writes the exact CODE -> N answer in the separate handover note before Apply.';
 let log=$('#logRows');log.replaceChildren();
 let ev=S.events.filter(e=>e.run===S.reset_count).slice(-22).reverse();
 for(const e of ev){let line=document.createElement('div');line.className='logEntry '+(e.result==='wrong_locked'||e.result==='masked'?'bad':e.result==='resolved'||e.result==='ok'?'good':'');let what=e.action==='handover_save'?'B saved shared note':e.action==='apply'?e.code+' · Action '+e.number:e.action==='test'?e.code+' · Test':e.action==='reset'?'SYSTEM · RESET':e.action;line.innerHTML='<b>T'+e.t+'</b>　'+what+'<br>'+nice(e.result);log.append(line)}
}
async function send(payload){
 if(busy||!S||S.terminated)return;busy=true;
 try{let r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();S=d.state;$('#statusline').textContent=nice(d.message);paint()}finally{busy=false}
}
$('#testBtn').addEventListener('click',()=>send({actor:'A',action:'test',code:chosen}));
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>send({actor:'A',action:'apply',code:chosen,number:Number(b.dataset.action)})));
$('#resetBtn').addEventListener('click',async()=>{if(busy||!S||S.terminated)return;if(!confirm('Reset all 10 faults? Reset count is permanent.'))return;let d=await fetch('/api/reset',{method:'POST'}).then(r=>r.json());S=d.state;chosen=S.faults[0].code;paint()});
reload();

